"use client";

import React, { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { FaRobot, FaTimes, FaPaperPlane } from "react-icons/fa";

interface Message {
  role: "bot" | "user";
  text: string;
}

const GeminiChatBot = ({ isOpen, onClose }: { isOpen: boolean; onClose: () => void }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: "bot", text: "Hi 👋 Welcome to Webkaro. How can I help you today?" }
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const endRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, loading]);

  /* ================= BOT LOGIC ================= */
  const getBotReply = (userText: string) => {
    const text = userText.toLowerCase();
    const responses = [];

    if (text.match(/price|cost|budget|charges|pricing/)) {
      responses.push(
        `💰 Pricing:
• Starter – ₹14,999
• Growth – ₹34,450
• Premium – ₹50,000`
      );
    }

    if (text.match(/service|services|work|offer|provide/)) {
      responses.push(
        `🛠 Services:
• Web Development
• UI/UX Design
• SaaS MVPs
• API Integration
• Maintenance`
      );
    }

    if (text.match(/website|web site|app|ecommerce|shop|store/)) {
      responses.push(
        `🌐 We build fast, modern websites, web apps & ecommerce platforms.`
      );
    }

    if (text.match(/ui|ux|design|redesign|figma/)) {
      responses.push(
        `🎨 UI/UX:
Clean, premium and conversion-focused designs.`
      );
    }

    if (text.match(/startup|mvp|saas/)) {
      responses.push(
        `🚀 Startup & MVP:
We help founders launch scalable MVPs quickly.`
      );
    }

    if (text.match(/time|duration|delivery|how long/)) {
      responses.push(
        `⏱ Timeline:
• Websites: 7–10 days
• Business sites: 2–3 weeks
• SaaS/MVP: 4–6 weeks`
      );
    }

    if (text.match(/urgent|fast|asap|quick/)) {
      responses.push(
        `⚡ Fast delivery available depending on scope.`
      );
    }

    if (text.match(/contact|call|phone|whatsapp|email/)) {
      responses.push(
        `📞 Contact:
Email: info@webkaro.in
WhatsApp: +91 88511 51976`
      );
    }

    if (text.match(/location|office|where|based/)) {
      responses.push(
        `📍 Location:
Delhi, India (working remotely across India)`
      );
    }

    if (responses.length > 0) return responses.join("\n\n");

    return `Thanks for reaching out 👋  
Tell me:
• What you want to build  
• Budget range  
• Timeline`;
  };

  /* ================= SEND HANDLER ================= */
  const handleSend = () => {
    if (!input.trim()) return;

    setMessages((prev) => [...prev, { role: "user", text: input }]);
    setInput("");
    setLoading(true);

    setTimeout(() => {
      setMessages((prev) => [
        ...prev,
        { role: "bot", text: getBotReply(input) }
      ]);
      setLoading(false);
    }, 600);
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0, scale: 0.9, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.9, y: 20 }}
          className="
          fixed bottom-24 left-6 z-[200]
          w-[350px]
          max-h-[75vh]
          bg-white dark:bg-zinc-900 rounded-2xl shadow-2xl
          flex flex-col overflow-hidden border border-border
        "
        >
          {/* HEADER */}
          <div className="bg-primary p-4 flex justify-between items-center flex-shrink-0">
            <div className="flex gap-2 items-center text-white">
              <FaRobot className="text-xl" />
              <div>
                <p className="font-bold text-sm">Webkaro Assistant</p>
                <p className="text-[10px] opacity-70">Always Online</p>
              </div>
            </div>

            <button
              onClick={onClose}
              className="text-white/80 hover:text-white hover:rotate-90 transition-all"
            >
              <FaTimes size={18} />
            </button>
          </div>

          {/* MESSAGES */}
          <div className="flex-1 overflow-y-auto p-4 bg-gray-50/50 dark:bg-zinc-800/50 scrollbar-hide">
            {messages.map((m, i) => (
              <div
                key={i}
                className={`flex mb-4 ${m.role === "user" ? "justify-end" : "justify-start"
                  }`}
              >
                <div
                  className={`max-w-[85%] p-3.5 rounded-2xl text-sm leading-relaxed shadow-sm ${m.role === "user"
                    ? "bg-primary text-white"
                    : "bg-white dark:bg-zinc-700 border border-border dark:border-white/5 text-foreground dark:text-white"
                    }`}
                >
                  {m.text}
                </div>
              </div>
            ))}

            {loading && (
              <div className="flex gap-2 items-center text-[10px] text-muted-foreground animate-pulse">
                <div className="w-1.5 h-1.5 bg-primary rounded-full" />
                Assistant is typing...
              </div>
            )}

            <div ref={endRef} />
          </div>

          {/* INPUT */}
          <form
            onSubmit={(e) => {
              e.preventDefault();
              handleSend();
            }}
            className="p-4 border-t border-border dark:border-white/10 bg-white dark:bg-zinc-900 flex gap-2 flex-shrink-0"
          >
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              className="flex-1 rounded-xl px-4 py-2 bg-gray-100 dark:bg-white/5 text-foreground dark:text-white outline-none border border-transparent focus:border-primary/30 transition-all text-sm"
              placeholder="How can we help?"
            />
            <button className="bg-primary text-white p-3 rounded-xl hover:bg-primary/90 transition-colors shadow-lg shadow-primary/20">
              <FaPaperPlane size={14} />
            </button>
          </form>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default GeminiChatBot;
